#include <iostream>
class Window {
    int low_ = 0, high_ = 0;

  public:
    bool reset(int a, int b) {
        if (a > b) {
            return false;
        }
        low_ = a;
        high_ = b;
        return true;
    }
    bool contains(int n) const { return low_ <= n && n <= high_; }
};
int main() {
    Window w;
    w.reset(2, 7);
    bool ok = w.reset(9, 1);
    std::cout << ok << ' ' << w.contains(4) << ' ' << w.contains(8) << '\n';
}

